  'deviceHealth.methodologyTitle': 'Scientific methodology & sources',
  'deviceHealth.methodBody.a': 'Every score, trend, and prediction in this dashboard is computed from transparent, cited formulas. International standards and peer-reviewed literature back each model — hover any source chip for the full citation, or open the ',
  'deviceHealth.references': 'References',
  'deviceHealth.methodBody.b': ' for the complete library with BibTeX / CSV export.',
  'deviceHealth.method.composite': 'Composite Health Score',
  'deviceHealth.method.compositeNote': 'A weighted composite of the three subsystems that most determine whether a node is useful: connectivity (lost link = no data), memory (heap exhaustion destabilises firmware) and uptime (sustained operation evidences a non-resetting node).',
  'deviceHealth.method.signal': 'Signal & RSSI Model',
  'deviceHealth.method.signalNote': 'RSSI is scaled to a 0–100 quality over the −90…−30 dBm usable window (IEEE 802.11 signal-strength reporting) and converted to an estimated device distance with the log-distance path-loss model (Friis 1946; ITU-R P.1238-11).',
  'deviceHealth.method.memory': 'Memory Health & Leak Detection',
  'deviceHealth.method.memoryNote': 'Free heap is scored against ESP32-class memory budgets (Espressif datasheet / TRM). A memory leak is declared when the ordinary least-squares slope of free heap over time is below −5 KB/hour — fast enough to threaten the device within days.',
  'deviceHealth.method.uncertainty': 'Measurement Uncertainty (GUM)',
  'deviceHealth.method.uncertaintyNote': 'Type-B standard uncertainty assumes a rectangular distribution over a declared relative accuracy. The expanded uncertainty (coverage factor k = 2) approximates a 95% confidence interval — the recommended reporting convention of the GUM (JCGM 100:2008).',
  'deviceHealth.method.trend': 'Trend & Remaining Useful Life (Prognostics)',
  'deviceHealth.method.trendNote': 'Trends are fitted with ordinary least squares and validated with R² (Moriasi et al. 2007). The Theil–Sen median slope estimator (Sen 1968) removes the influence of outliers, and the remaining useful life extrapolates the health slope to a failure threshold (ISO 13381-1:2015).',
  'deviceHealth.method.sources': 'Sources',
  'deviceHealth.refresh': 'Refresh',
  'deviceHealth.tab.overview': 'Overview',
  'deviceHealth.tab.alerts': 'Alerts',
  'deviceHealth.trend.none': 'No trend',
  'deviceHealth.trend.improving': 'Improving',
  'deviceHealth.trend.degrading': 'Degrading',
  'deviceHealth.trend.stable': 'Stable',
  'deviceHealth.trendConfidence': 'Trend confidence',
