  'support.category.security': 'Security',
  'support.faqNoResults': 'No FAQs match your search.',
  'support.faq.1.question': 'How do I connect my first IoT device?',
  'support.faq.1.answer': 'Navigate to Device Connection, select your protocol (MQTT recommended), and configure the broker URL. Your ESP32 or NodeMCU device should publish to pern/sensors/{device_id}/data with JSON payloads containing your sensor readings.',
  'support.faq.2.question': 'What sensors does the platform support?',
  'support.faq.2.answer': 'We support 13 physical sensors: PM2.5, PM10, CO, CO2, NO2, SO2, O3, pH, Temperature, Humidity, TDS, Turbidity, and Dissolved Oxygen. These feed into 9+ virtual sensor computations.',
  'support.faq.3.question': 'How is the EHI score calculated?',
  'support.faq.3.answer': 'The Environmental Health Index is a composite score (0-100) using 6 weighted sub-indices: Air Quality, Water Quality, Human Safety, Ecosystem Health, Sustainability, and Stability. It uses the scientific formula defined in our research documentation.',
  'support.faq.4.question': 'How many devices can I connect simultaneously?',
  'support.faq.4.answer': 'Free tier supports 3 devices, Pro supports 25, and Enterprise offers unlimited. Each device can publish readings at intervals as low as 5 seconds via MQTT.',
  'support.faq.5.question': 'My device keeps disconnecting. What should I do?',
  'support.faq.5.answer': 'Check the Device Health Dashboard for battery and connectivity scores. Ensure your MQTT broker is running (mosquitto), verify WiFi signal strength at the device location, and check that keepalive intervals are properly configured (recommended: 60s).',
  'support.faq.6.question': 'Can I update device firmware remotely?',
  'support.faq.6.answer': 'Yes! Go to Firmware Management to view current firmware versions across devices. OTA (Over-The-Air) simulation is available for testing, with full OTA rollout planned for Enterprise tier.',
  'support.faq.7.question': 'How do I set up automated alerts?',
  'support.faq.7.answer': 'Go to Automation Engine and create rules with conditions (e.g., IF pm25 > 45 THEN activate fan). Rules execute every 8 seconds, support cooldown periods, and send real push notifications via ntfy.sh.',
  'support.faq.8.question': 'What notification channels are supported?',
  'support.faq.8.answer': 'Currently ntfy.sh push notifications (cross-platform, free), email alerts (Enterprise), and in-app notifications. Slack and Microsoft Teams webhooks are on the roadmap.',
  'support.faq.9.question': 'How do I export my data?',
  'support.faq.9.answer': 'Use the Sensors page export buttons for CSV and Excel formats. Reports page generates PDF reports for 6 different analysis types. Historical data can be exported from the History page.',
  'support.faq.10.question': 'What is the prediction accuracy?',
  'support.faq.10.answer': 'Our ensemble model (Linear Trend + Moving Average + Weather-informed) typically achieves 85-92% accuracy for 24-hour forecasts. Check the Predictions page for real-time accuracy validation scores.',
  'support.faq.11.question': 'How is my data protected?',
  'support.faq.11.answer': 'Data is encrypted in transit (TLS/SSL) and at rest (PostgreSQL column-level encryption). We support Logto OIDC authentication, role-based access control (owner/admin/member/viewer), and full audit logging with 90-day retention.',
  'support.faq.12.question': 'Can I integrate with our existing auth system?',
  'support.faq.12.answer': 'Yes! We support Logto OIDC out of the box. Configure your tenant ID and app ID in the backend .env file. SAML and custom OAuth2 providers are supported on Enterprise tier.',
