  'setupGuide.faq.noSerialSol': '\u062a\u062d\u0642\u0642 \u0645\u0646 \u0623\u0646 \u0645\u0639\u062f\u0644 \u0627\u0644\u0628\u062b 115200 \u0641\u064a Serial Monitor. \u0627\u0641\u062d\u0635 \u0627\u0644\u062a\u0648\u0635\u064a\u0644\u0627\u062a \u2014 \u062e\u0627\u0635\u0629 VCC \u0648GND.',
  'setupGuide.faq.wifiFail': 'ESP32: \u0641\u0634\u0644 \u0627\u062a\u0635\u0627\u0644 WiFi',
  'setupGuide.faq.wifiFailSol': '\u062a\u0623\u0643\u062f \u0645\u0646 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 WiFi \u0628\u062a\u0631\u062f\u062f 2.4GHz (\u0644\u0627 \u064a\u062f\u0639\u0645 ESP32 \u062a\u0631\u062f\u062f 5GHz). \u062a\u062d\u0642\u0642 \u0645\u0646 \u0635\u062d\u0629 \u0627\u0633\u0645 \u0627\u0644\u0634\u0628\u0643\u0629/\u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631.',
  'setupGuide.faq.mqttFail': '\u0641\u0634\u0644 \u0627\u062a\u0635\u0627\u0644 MQTT',
  'setupGuide.faq.mqttFailSol': '\u0634\u063a\u0651\u0644 "mosquitto -h" \u0644\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u062a\u062b\u0628\u064a\u062a Mosquitto. \u062a\u0623\u0643\u062f \u0645\u0646 \u0623\u0646 \u0627\u0644\u0645\u0646\u0641\u0630 1883 \u063a\u064a\u0631 \u0645\u062d\u062c\u0648\u0628 \u0628\u0648\u0627\u0633\u0637\u0629 \u062c\u062f\u0627\u0631 \u0627\u0644\u062d\u0645\u0627\u064a\u0629.',
  'setupGuide.faq.unstable': '\u0642\u0631\u0627\u0621\u0627\u062a \u063a\u064a\u0631 \u0645\u0633\u062a\u0642\u0631\u0629',
  'setupGuide.faq.unstableSol': '\u0623\u0636\u0641 \u0645\u0643\u062b\u0641\u0627\u062a \u0641\u0635\u0644 100nF \u0639\u0644\u0649 \u0623\u0637\u0631\u0627\u0641 VCC \u0644\u0644\u0645\u0633\u062a\u0634\u0639\u0631\u0627\u062a. \u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0642\u0635\u0631 \u0623\u0633\u0644\u0627\u0643 \u0627\u0644\u0625\u0634\u0627\u0631\u0629 \u0627\u0644\u062a\u0646\u0627\u0638\u0631\u064a\u0629. \u062a\u062c\u0646\u0628 \u062a\u0645\u0631\u064a\u0631 \u0623\u0633\u0644\u0627\u0643 \u0627\u0644\u0645\u0633\u062a\u0634\u0639\u0631\u0627\u062a \u0628\u0627\u0644\u0642\u0631\u0628 \u0645\u0646 \u0643\u0627\u0628\u0644\u0627\u062a \u0627\u0644\u0637\u0627\u0642\u0629.',
  'setupGuide.faq.dhtNan': '\u064a\u064f\u0631\u062c\u0639 DHT22 \u0642\u064a\u0645\u0629 NaN',
  'setupGuide.faq.dhtNanSol': '\u0623\u0636\u0641 \u0645\u0642\u0627\u0648\u0645\u0629 \u0633\u062d\u0628 10k\u03a9 \u0628\u064a\u0646 DATA \u0648VCC. \u062a\u0623\u0643\u062f \u0645\u0646 \u0623\u0646 \u0627\u0644\u0645\u0633\u062a\u0634\u0639\u0631 \u062d\u0635\u0644 \u0639\u0644\u0649 \u062b\u0627\u0646\u064a\u062a\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644 \u0644\u0644\u062a\u0647\u064a\u0626\u0629.',
