  'deviceHealth.methodologyTitle': '\u0627\u0644\u0645\u0646\u0647\u062c\u064a\u0629 \u0627\u0644\u0639\u0644\u0645\u064a\u0629 \u0648\u0627\u0644\u0645\u0635\u0627\u062f\u0631',
  'deviceHealth.methodBody.a': '\u062a\u064f\u062d\u0633\u0628 \u0643\u0644 \u062f\u0631\u062c\u0629 \u0648\u0627\u062a\u062c\u0627\u0647 \u0648\u062a\u0646\u0628\u0624 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0644\u0648\u062d\u0629 \u0645\u0646 \u0635\u064a\u063a \u0634\u0641\u0627\u0641\u0629 \u0648\u0645\u0648\u062b\u0642\u0629. \u062a\u062f\u0639\u0645 \u0627\u0644\u0645\u0639\u0627\u064a\u064a\u0631 \u0627\u0644\u062f\u0648\u0644\u064a\u0629 \u0648\u0627\u0644\u0623\u0628\u062d\u0627\u062b \u0627\u0644\u0645\u062d\u0643\u0645\u0629 \u0643\u0644 \u0646\u0645\u0648\u0630\u062c \u2014 \u0645\u0631\u0651\u0631 \u0641\u0648\u0642 \u0623\u064a \u0634\u0627\u0631\u0629 \u0645\u0635\u062f\u0631 \u0644\u0644\u0627\u0642\u062a\u0628\u0627\u0633 \u0627\u0644\u0643\u0627\u0645\u0644\u060c \u0623\u0648 \u0627\u0641\u062a\u062d \u0635\u0641\u062d\u0629 ',
  'deviceHealth.references': '\u0627\u0644\u0645\u0631\u0627\u062c\u0639',
  'deviceHealth.methodBody.b': ' \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0645\u0643\u062a\u0628\u0629 \u0627\u0644\u0643\u0627\u0645\u0644\u0629 \u0645\u0639 \u062a\u0635\u062f\u064a\u0631 BibTeX / CSV.',
  'deviceHealth.method.composite': '\u062f\u0631\u062c\u0629 \u0627\u0644\u0635\u062d\u0629 \u0627\u0644\u0645\u0631\u0643\u0628\u0629',
  'deviceHealth.method.compositeNote': '\u0645\u062c\u0645\u0648\u0639\u0629 \u0645\u0631\u062c\u062d\u0629 \u0645\u0646 \u0627\u0644\u0623\u0646\u0638\u0645\u0629 \u0627\u0644\u0641\u0631\u0639\u064a\u0629 \u0627\u0644\u062b\u0644\u0627\u062b\u0629 \u0627\u0644\u062a\u064a \u062a\u062d\u062f\u062f \u0641\u0627\u0626\u062f\u0629 \u0627\u0644\u0639\u0642\u062f\u0629: \u0627\u0644\u0627\u062a\u0635\u0627\u0644 (\u0641\u0642\u062f\u0627\u0646 \u0627\u0644\u0627\u062a\u0635\u0627\u0644 = \u0644\u0627 \u0628\u064a\u0627\u0646\u0627\u062a)\u060c \u0648\u0627\u0644\u0630\u0627\u0643\u0631\u0629 (\u0627\u0633\u062a\u0646\u0641\u0627\u062f \u0627\u0644\u0643\u0648\u0645\u0629 \u064a\u0632\u0639\u0632\u0639 \u0627\u0633\u062a\u0642\u0631\u0627\u0631 \u0627\u0644\u0628\u0631\u0646\u0627\u0645\u062c \u0627\u0644\u062b\u0627\u0628\u062a)\u060c \u0648\u0645\u062f\u0629 \u0627\u0644\u062a\u0634\u063a\u064a\u0644 (\u0627\u0644\u062a\u0634\u063a\u064a\u0644 \u0627\u0644\u0645\u0633\u062a\u0645\u0631 \u064a\u062b\u0628\u062a \u0623\u0646 \u0627\u0644\u0639\u0642\u062f\u0629 \u0644\u0627 \u064a\u064f\u0639\u0627\u062f \u062a\u0634\u063a\u064a\u0644\u0647\u0627).',
  'deviceHealth.method.signal': '\u0646\u0645\u0648\u0630\u062c \u0627\u0644\u0625\u0634\u0627\u0631\u0629 \u0648RSSI',
  'deviceHealth.method.signalNote': '\u064a\u062a\u0645 \u062a\u062d\u0648\u064a\u0644 RSSI \u0625\u0644\u0649 \u062c\u0648\u062f\u0629 \u0645\u0646 0 \u0625\u0644\u0649 100 \u0639\u0644\u0649 \u0646\u0627\u0641\u0630\u0629 \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0645\u0646 \u221290\u2026\u221230 dBm (\u0625\u0628\u0644\u0627\u063a \u0642\u0648\u0629 \u0627\u0644\u0625\u0634\u0627\u0631\u0629 IEEE 802.11) \u0648\u062a\u062d\u0648\u064a\u0644\u0647 \u0625\u0644\u0649 \u0645\u0633\u0627\u0641\u0629 \u062a\u0642\u062f\u064a\u0631\u064a\u0629 \u0644\u0644\u062c\u0647\u0627\u0632 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0646\u0645\u0648\u0630\u062c \u0641\u0642\u062f\u0627\u0646 \u0627\u0644\u0645\u0633\u0627\u0631 \u0627\u0644\u0644\u0648\u063a\u0627\u0631\u064a\u062a\u0645\u064a (Friis 1946; ITU-R P.1238-11).',
  'deviceHealth.method.memory': '\u0635\u062d\u0629 \u0627\u0644\u0630\u0627\u0643\u0631\u0629 \u0648\u0627\u0643\u062a\u0634\u0627\u0641 \u0627\u0644\u062a\u0633\u0631\u0628',
  'deviceHealth.method.memoryNote': '\u064a\u062a\u0645 \u062a\u0642\u064a\u064a\u0645 \u0627\u0644\u0630\u0627\u0643\u0631\u0629 \u0627\u0644\u062d\u0631\u0629 \u0648\u0641\u0642 \u0645\u0648\u0627\u0632\u064a\u0646 \u0630\u0627\u0643\u0631\u0629 \u0645\u0646 \u0641\u0626\u0629 ESP32 (\u0635\u062d\u064a\u0641\u0629 \u0628\u064a\u0627\u0646\u0627\u062a Espressif / TRM). \u064a\u064f\u0639\u0644\u0646 \u0639\u0646 \u062a\u0633\u0631\u0628 \u0627\u0644\u0630\u0627\u0643\u0631\u0629 \u0639\u0646\u062f\u0645\u0627 \u064a\u0646\u062e\u0641\u0636 \u0645\u064a\u0644 \u0627\u0644\u0645\u0631\u0628\u0639\u0627\u062a \u0627\u0644\u0635\u063a\u0631\u0649 \u0644\u0644\u0630\u0627\u0643\u0631\u0629 \u0627\u0644\u062d\u0631\u0629 \u0639\u0628\u0631 \u0627\u0644\u0632\u0645\u0646 \u0639\u0646 \u22125 \u0643\u064a\u0644\u0648\u0628\u0627\u064a\u062a/\u0633\u0627\u0639\u0629 \u2014 \u0648\u0647\u0648 \u0645\u0627 \u064a\u0643\u0641\u064a \u0644\u062a\u0647\u062f\u064a\u062f \u0627\u0644\u062c\u0647\u0627\u0632 \u062e\u0644\u0627\u0644 \u0623\u064a\u0627\u0645.',
  'deviceHealth.method.uncertainty': '\u0639\u062f\u0645 \u0627\u0644\u064a\u0642\u064a\u0646 \u0641\u064a \u0627\u0644\u0642\u064a\u0627\u0633 (GUM)',
  'deviceHealth.method.uncertaintyNote': '\u064a\u0641\u062a\u0631\u0636 \u0639\u062f\u0645 \u0627\u0644\u064a\u0642\u064a\u0646 \u0627\u0644\u0642\u064a\u0627\u0633\u064a \u0645\u0646 \u0627\u0644\u0646\u0648\u0639 B \u062a\u0648\u0632\u064a\u0639\u064b\u0627 \u0645\u0633\u062a\u0637\u064a\u0644\u064b\u0627 \u0639\u0644\u0649 \u062f\u0642\u0629 \u0646\u0633\u0628\u064a\u0629 \u0645\u0639\u0644\u0646\u0629. \u0648\u064a\u0642\u0627\u0631\u0628 \u0639\u062f\u0645 \u0627\u0644\u064a\u0642\u064a\u0646 \u0627\u0644\u0645\u0648\u0633\u0639 (\u0645\u0639\u0627\u0645\u0644 \u0627\u0644\u062a\u063a\u0637\u064a\u0629 k = 2) \u0641\u0627\u0635\u0644 \u062b\u0642\u0629 95% \u2014 \u0648\u0647\u0648 \u0623\u0633\u0644\u0648\u0628 \u0627\u0644\u0625\u0628\u0644\u0627\u063a \u0627\u0644\u0645\u0648\u0635\u0649 \u0628\u0647 \u0641\u064a GUM (JCGM 100:2008).',
  'deviceHealth.method.trend': '\u0627\u0644\u0627\u062a\u062c\u0627\u0647 \u0648\u0627\u0644\u0639\u0645\u0631 \u0627\u0644\u0625\u0646\u062a\u0627\u062c\u064a \u0627\u0644\u0645\u062a\u0628\u0642\u064a (\u0627\u0644\u062a\u0646\u0628\u0624)',
  'deviceHealth.method.trendNote': '\u062a\u064f\u0644\u0627\u0626\u0645 \u0627\u0644\u0627\u062a\u062c\u0627\u0647\u0627\u062a \u0628\u0627\u0644\u0645\u0631\u0628\u0639\u0627\u062a \u0627\u0644\u0635\u063a\u0631\u0649 \u0627\u0644\u0639\u0627\u062f\u064a\u0629 \u0648\u062a\u064f\u062a\u062d\u0642\u0642 \u0628\u0640 R\u00b2 (Moriasi et al. 2007). \u064a\u0632\u064a\u0644 \u0645\u0642\u062f\u0651\u0631 \u0627\u0644\u0645\u0646\u062d\u062f\u0631 \u0627\u0644\u0648\u0633\u064a\u0637 Theil\u2013Sen (Sen 1968) \u062a\u0623\u062b\u064a\u0631 \u0627\u0644\u0642\u064a\u0645 \u0627\u0644\u0634\u0627\u0630\u0629\u060c \u0648\u064a\u0633\u062a\u0642\u0631\u0626 \u0627\u0644\u0639\u0645\u0631 \u0627\u0644\u0625\u0646\u062a\u0627\u062c\u064a \u0627\u0644\u0645\u062a\u0628\u0642\u064a \u0645\u0646\u062d\u062f\u0631 \u0627\u0644\u0635\u062d\u0629 \u0625\u0644\u0649 \u0639\u062a\u0628\u0629 \u0627\u0644\u0641\u0634\u0644 (ISO 13381-1:2015).',
