  'support.form.submit': '\u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u062a\u0630\u0643\u0631\u0629',
  'support.toast.fillRequired': '\u064a\u0631\u062c\u0649 \u0645\u0644\u0621 \u062c\u0645\u064a\u0639 \u0627\u0644\u062d\u0642\u0648\u0644 \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629',
  'support.toast.submitted': '\u062a\u0645 \u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u062a\u0630\u0643\u0631\u0629 \u0628\u0646\u062c\u0627\u062d! \u0633\u0646\u0631\u062f \u062e\u0644\u0627\u0644 4 \u0633\u0627\u0639\u0627\u062a.',
  'support.toast.submittedDemo': '\u062a\u0645 \u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u062a\u0630\u0643\u0631\u0629! (\u0648\u0636\u0639 \u0627\u0644\u0639\u0631\u0636 \u2014 \u0633\u064a\u0639\u0627\u0644\u062c\u0647\u0627 \u0627\u0644\u062e\u0627\u062f\u0645 \u0639\u0646\u062f \u062a\u0648\u0641\u0631\u0647)',
