const dictionaries: Record<Locale, Record<string, string>> = { en, ar };

function lookup(dict: Record<string, string>, key: string): string {
  if (key in dict) return dict[key];
  const parts = key.split('.');
  // Try progressively shorter keys (e.g. "nav.dashboard" -> look up "dashboard")
  if (parts.length > 1) {
    const shortKey = parts[parts.length - 1];
    if (shortKey in dict) return dict[shortKey];
  }
  return key;
}

function interpolate(str: string, params?: Interpolation): string {
  if (!params) return str;
  for (const [k, v] of Object.entries(params)) {
    str = str.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v));
  }
  return str;
}

function translate(
  dict: Record<string, string>,
  key: string,
  fallback?: string,
  params?: Interpolation,
): string {
  let str = lookup(dict, key);
  if (str === key && fallback) str = fallback;
  return interpolate(str, params);
}

function detectInitialLocale(): Locale {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored === 'en' || stored === 'ar') return stored;
  } catch { /* ignore */ }
  try {
    // Default to Arabic for Arabic-browser users on first visit
    const lang = (navigator.language || '').toLowerCase();
    if (lang.startsWith('ar')) return 'ar';
  } catch { /* ignore */ }
  return 'en';
}

/* ─── Provider ─── */

export function I18nProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>(detectInitialLocale);

  const setLocale = useCallback((l: Locale) => {
    setLocaleState(l);
    try { localStorage.setItem(STORAGE_KEY, l); } catch { /* ignore */ }
  }, []);

  // Sync <html> dir & lang attributes
  useEffect(() => {
    document.documentElement.dir = locale === 'ar' ? 'rtl' : 'ltr';
    document.documentElement.lang = locale;
  }, [locale]);

  const t = useCallback(
    (key: string, fallback?: string, params?: Interpolation) =>
      translate(dictionaries[locale], key, fallback, params),
    [locale],
  );

  const dir = locale === 'ar' ? 'rtl' : 'ltr';

  return (
    <I18nContext.Provider value={{ locale, setLocale, t, dir }}>
      {children}
    </I18nContext.Provider>
  );
}

export function useI18n() {
  const ctx = useContext(I18nContext);
  if (!ctx) throw new Error('useI18n must be used within I18nProvider');
  const tWithInterp = useCallback(
    (key: string, fallback?: string, params?: Interpolation) =>
      translate(dictionaries[ctx.locale], key, fallback, params),
    [ctx.locale],
  );
  return { ...ctx, t: tWithInterp };
}
